// ── CAMBIE SOLO ESTAS TRES LÍNEAS ─────────────────────────────
const HOST   = "IP_PUBLICA";     // IP o DNS público de su VM en AWS
const ORG    = "unipamplona";    // INFLUX_ORG del archivo .env
const BUCKET = "uns";            // INFLUX_BUCKET del archivo .env
// El token NO va aquí: va en el nodo «Escribir en InfluxDB»,
// campo Token (así no queda dentro del flujo exportado).
// ──────────────────────────────────────────────────────────────

// Tópico: empresa/sitio/area/linea/celda/dispositivo/clase/variable
const n = msg.topic.split("/");
if (n.length !== 8) {
    node.warn("Tópico con " + n.length + " niveles, se esperaban 8: " + msg.topic);
    return null;
}
const nombres = ["empresa", "sitio", "area", "linea", "celda", "dispositivo"];

// Extraer el número: acepta {"valor":42.5,...} o un número suelto
const p = msg.payload;
const valor = Number((p !== null && typeof p === "object") ? p.valor : p);
if (!Number.isFinite(valor)) {
    node.warn("Mensaje sin valor numérico en " + msg.topic);
    return null;
}

// En el protocolo de línea, espacios, comas e iguales se escapan
const esc = (s) => String(s).replace(/([ ,=])/g, "\\$1");

let etiquetas = nombres.map((k, i) => k + "=" + esc(n[i]));
etiquetas.push("variable=" + esc(n[7]));
if (p && p.unidad)  etiquetas.push("unidad="  + esc(p.unidad));
if (p && p.calidad) etiquetas.push("calidad=" + esc(p.calidad));

// medicion,empresa=...,variable=potenciometro valor=42.5 1730000000000
msg.payload = esc(n[6]) + "," + etiquetas.join(",") +
              " valor=" + valor + " " + Date.now();

msg.url = "http://" + HOST + ":8086/api/v2/write" +
          "?org=" + encodeURIComponent(ORG) +
          "&bucket=" + encodeURIComponent(BUCKET) +
          "&precision=ms";
msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
node.status({ fill: "blue", shape: "dot", text: n[5] + "/" + n[7] + " = " + valor });
return msg;

// InfluxDB responde 204 cuando escribió el punto
if (msg.statusCode === 204) {
    node.status({ fill: "green", shape: "dot", text: "204 · escrito" });
} else {
    node.status({ fill: "red", shape: "ring", text: msg.statusCode + " · ver depuración" });
    return msg;
}
return null;
